select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"work_id":987102017,"language":"nl"},"seq":1,"relation":"catalog_work_descriptions","after_row":{"text":"Hiroko Tanaka overleeft in 1945 de atoombom op Nagasaki, maar verliest de wereld waarin zij haar toekomst zag. Twee jaar later reist ze naar Delhi en zoekt contact met de familie van haar verloofde. Daar ontstaan banden die haar leven met andere gezinnen verbinden. Die relaties blijven over generaties en landsgrenzen bestaan, terwijl nieuwe oorlogen eerdere verliezen niet laten verdwijnen. Kamila Shamsie volgt hoe persoonlijke loyaliteit en politieke conflicten elkaar beïnvloeden van Azië tot de Verenigde Staten en Afghanistan.","work_id":987102017,"evidence":[{"note":"Exact ISBN9789045800738, Dutch KB title, Kamila Shamsie and Burnt shadows2009 agree; same complete novel across countries, not a new Work.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p318218402"],"reference":"work:5005","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-032.json","sources":["https://openlibrary.org/works/OL1041829W","https://data.bibliotheken.nl/id/nbt/p318218402"]},{"type":"cover_front_review","sha256":"66a55e58e60de5d8cd20fe52d8d0eefd2fdb2f98babc840de0aa2121f0b04158","cover_id":13780622,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL1041829W","reviewed_at":"2026-11-02T17:01:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_author_id":987302003},"before_row":null},{"key":{"edition_id":987202021},"seq":2,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987102017,"evidence":[{"note":"Exact ISBN9789045800738, Dutch KB title, Kamila Shamsie and Burnt shadows2009 agree; same complete novel across countries, not a new Work.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p318218402"],"reference":"work:5005","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-032.json","sources":["https://openlibrary.org/works/OL1041829W","https://data.bibliotheken.nl/id/nbt/p318218402"]},{"type":"cover_front_review","sha256":"66a55e58e60de5d8cd20fe52d8d0eefd2fdb2f98babc840de0aa2121f0b04158","cover_id":13780622,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/13780622-L.jpg?default=false","edition_id":987202021,"bound_title":"Verbrande schaduwen","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789045800738","evidence_url":"https://data.bibliotheken.nl/id/nbt/p318218402","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13780622-M.jpg?default=false","bound_author_id":987302003},"before_row":null},{"key":{"work_id":987102012,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"De laatste overlevenden van de mensheid verlaten een stervende aarde en zoeken aan de hand van oude sterrenkaarten een nieuwe woonplaats. Een planeet die hun voorouders geschikt hebben gemaakt voor leven lijkt uitkomst te bieden. Bij aankomst blijkt die wereld echter niet leeg. Een andere beschaving heeft er haar eigen ontwikkeling doorgemaakt. Het vooruitzicht op een veilige toekomst verandert daardoor in een botsing tussen samenlevingen die elk hun voortbestaan willen verzekeren. De roman onderzoekt wie aanspraak kan maken op deze nieuwe wereld.","work_id":987102012,"evidence":[{"note":"Exact ISBN9789083267432 identifies Dutch translation of Children of time2015. Adrian Tchaikovsky and front match, not Children of Ruin or Children of Memory.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p440086205"],"reference":"work:3285","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL17373843W","https://data.bibliotheken.nl/id/nbt/p440086205"]},{"type":"cover_front_review","sha256":"421a376d97f65ee9e09312bc2f1b79e9fa5b63806220ad12dfd1df9fbad3d427","cover_id":14550907,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL17373843W","reviewed_at":"2026-11-02T17:01:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_author_id":987302006},"before_row":null},{"key":{"edition_id":987202016},"seq":4,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987102012,"evidence":[{"note":"Exact ISBN9789083267432 identifies Dutch translation of Children of time2015. Adrian Tchaikovsky and front match, not Children of Ruin or Children of Memory.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p440086205"],"reference":"work:3285","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL17373843W","https://data.bibliotheken.nl/id/nbt/p440086205"]},{"type":"cover_front_review","sha256":"421a376d97f65ee9e09312bc2f1b79e9fa5b63806220ad12dfd1df9fbad3d427","cover_id":14550907,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/14550907-L.jpg?default=false","edition_id":987202016,"bound_title":"Kinderen van de tijd","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789083267432","evidence_url":"https://data.bibliotheken.nl/id/nbt/p440086205","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14550907-M.jpg?default=false","bound_author_id":987302006},"before_row":null},{"key":{"id":987202001},"seq":5,"relation":"editions","after_row":{"id":987202001,"title":"Peachez, een romance","isbn_10":null,"isbn_13":"9789029511643","work_id":987102001,"cover_id":null,"language":"dut","publisher":"De Arbeiderspers","publish_date":null,"open_library_edition_id":"OL27403436M"},"before_row":{"id":987202001,"title":"Peachez, een romance","isbn_10":null,"isbn_13":"9789029511643","work_id":987102001,"cover_id":null,"language":null,"publisher":"De Arbeiderspers","publish_date":null,"open_library_edition_id":"OL27403436M"}},{"key":{"work_id":987102001,"language":"nl"},"seq":6,"relation":"catalog_work_descriptions","after_row":{"text":"Een professor raakt via internet in contact met een vrouw die zich als fotomodel presenteert. Hun uitwisseling groeit uit tot een liefde die zijn bestaan steeds sterker bepaalt. Afstand en verbeelding geven de verhouding een eigen werkelijkheid. De roman onderzoekt hoe iemand in een overtuigend verhaal kan gaan leven en hoeveel zekerheid een geliefde werkelijk over de ander kan hebben. Achter het hedendaagse verschijnsel catfishing ligt zo een bredere vraag naar verlangen, vertrouwen en de betekenis van liefde.","work_id":987102001,"evidence":[{"note":"Existing edition1044 has exact Dutch title/ISBN9789029511643 but missing language. KB confirms Dutch original by Ilja Leonard Pfeijffer; repair language, not duplicate Work or edition.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p407938680"],"reference":"work:1044","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-019.json","sources":["https://openlibrary.org/works/OL20214285W","https://data.bibliotheken.nl/id/nbt/p407938680"]},{"type":"cover_front_review","sha256":"6ef7d999eaccf47c6e27472a6aab3ff56b6f342ee66782a96c79a090aa8670c0","cover_id":8865775,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL20214285W","reviewed_at":"2026-11-02T17:01:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_author_id":930300014},"before_row":null},{"key":{"edition_id":987202001},"seq":7,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":987102001,"evidence":[{"note":"Existing edition1044 has exact Dutch title/ISBN9789029511643 but missing language. KB confirms Dutch original by Ilja Leonard Pfeijffer; repair language, not duplicate Work or edition.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p407938680"],"reference":"work:1044","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-019.json","sources":["https://openlibrary.org/works/OL20214285W","https://data.bibliotheken.nl/id/nbt/p407938680"]},{"type":"cover_front_review","sha256":"6ef7d999eaccf47c6e27472a6aab3ff56b6f342ee66782a96c79a090aa8670c0","cover_id":8865775,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/8865775-L.jpg?default=false","edition_id":987202001,"bound_title":"Peachez, een romance","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789029511643","evidence_url":"https://data.bibliotheken.nl/id/nbt/p407938680","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/8865775-M.jpg?default=false","bound_author_id":930300014},"before_row":null},{"key":{"work_id":987102013,"language":"nl"},"seq":8,"relation":"catalog_work_descriptions","after_row":{"text":"Na een zwaar bouwongeluk en het einde van zijn huwelijk verhuist Edgar Freemantle naar Florida. Op Duma Key begint hij opnieuw te schilderen. Zijn talent biedt aanvankelijk houvast, maar zijn werk blijkt ook een onverklaarbare invloed te kunnen uitoefenen. Via nieuwe vrienden raakt hij betrokken bij de geschiedenis van het eiland en de herinneringen van Elizabeth Eastlake. Wat als herstel op een andere plek begon, brengt hem zo dichter bij een dreiging die met kunst en het verleden verbonden is.","work_id":987102013,"evidence":[{"note":"Exact ISBN9789024528080 and KB original Duma key2008 establish Duma as same full novel. Existing Dutch edition3458 retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p308187032"],"reference":"work:3299","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://stephenking.com/works/novel/duma-key.html","https://openlibrary.org/works/OL149119W","https://data.bibliotheken.nl/id/nbt/p308187032"]},{"type":"cover_front_review","sha256":"ffa931fe2d0b7ce08c2f0a8eba7a9afe1c1f48ef617b9cfcb09f0fd6d8adce64","cover_id":14653088,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://stephenking.com/works/novel/duma-key.html","reviewed_at":"2026-11-02T17:01:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_author_id":928300049},"before_row":null},{"key":{"edition_id":987202017},"seq":9,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987102013,"evidence":[{"note":"Exact ISBN9789024528080 and KB original Duma key2008 establish Duma as same full novel. Existing Dutch edition3458 retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p308187032"],"reference":"work:3299","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://stephenking.com/works/novel/duma-key.html","https://openlibrary.org/works/OL149119W","https://data.bibliotheken.nl/id/nbt/p308187032"]},{"type":"cover_front_review","sha256":"ffa931fe2d0b7ce08c2f0a8eba7a9afe1c1f48ef617b9cfcb09f0fd6d8adce64","cover_id":14653088,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/14653088-L.jpg?default=false","edition_id":987202017,"bound_title":"Duma","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789024528080","evidence_url":"https://data.bibliotheken.nl/id/nbt/p308187032","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14653088-M.jpg?default=false","bound_author_id":928300049},"before_row":null},{"key":{"work_id":987102010,"language":"nl"},"seq":10,"relation":"catalog_work_descriptions","after_row":{"text":"In Castle Rock opent Leland Gaunt een winkel met voorwerpen die voor zijn klanten een bijzondere aantrekkingskracht hebben. De prijs bestaat niet alleen uit geld: kopers moeten ook iets voor hem doen. Wat onschuldige streken lijken, grijpt in op bestaande irritaties en tegenstellingen tussen inwoners. Terwijl steeds meer mensen vinden wat zij denken nodig te hebben, wordt hun onderlinge verhouding gevaarlijker. Sheriff Alan Pangborn komt tegenover een onrust te staan waarvan de afzonderlijke oorzaken moeilijk te overzien zijn.","work_id":987102010,"evidence":[{"note":"Exact Dutch ISBN9789024519880, Stephen Edwin King canonical name and original Needful things1991 agree. Existing edition3427 retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p088870561","http://data.bibliotheken.nl/id/nbt/p141168803"],"reference":"work:3268","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL81607W","https://data.bibliotheken.nl/id/nbt/p088870561","https://data.bibliotheken.nl/id/nbt/p141168803"]},{"type":"cover_front_review","sha256":"92457148f556b00958aff73fa1ef791d24f9e71f036e0f41a53d8f3c25a59abe","cover_id":14653583,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL81607W","reviewed_at":"2026-11-02T17:01:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_author_id":928300049},"before_row":null},{"key":{"edition_id":987202014},"seq":11,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987102010,"evidence":[{"note":"Exact Dutch ISBN9789024519880, Stephen Edwin King canonical name and original Needful things1991 agree. Existing edition3427 retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p088870561","http://data.bibliotheken.nl/id/nbt/p141168803"],"reference":"work:3268","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL81607W","https://data.bibliotheken.nl/id/nbt/p088870561","https://data.bibliotheken.nl/id/nbt/p141168803"]},{"type":"cover_front_review","sha256":"92457148f556b00958aff73fa1ef791d24f9e71f036e0f41a53d8f3c25a59abe","cover_id":14653583,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/14653583-L.jpg?default=false","edition_id":987202014,"bound_title":"De noodzaak","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789024519880","evidence_url":"https://data.bibliotheken.nl/id/nbt/p088870561","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14653583-M.jpg?default=false","bound_author_id":928300049},"before_row":null},{"key":{"work_id":987102014,"language":"nl"},"seq":12,"relation":"catalog_work_descriptions","after_row":{"text":"Een onbekende laat bij een tankstation in Pennsylvania een opvallend goed onderhouden Buick achter. De politie brengt de auto naar een schuur bij het bureau, waar hij niet zomaar een gevonden voorwerp blijkt te zijn. Rond de wagen doen zich onverklaarbare verschijnselen voor die de agenten jarenlang bezighouden. Wanneer de zoon van een overleden politieman op het bureau komt werken, wil hij begrijpen welke rol de Buick heeft gespeeld. Zijn vragen brengen de anderen ertoe hun ervaringen met de auto te vertellen.","work_id":987102014,"evidence":[{"note":"Exact Dutch ISBN9789024539147 binds to From a Buick8. KB copyright2001 does not replace confirmed original release24September2002; retain current2002.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p238264815"],"reference":"work:3325","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["https://stephenking.com/works/novel/from-a-buick-8.html","https://openlibrary.org/works/OL81586W","https://data.bibliotheken.nl/id/nbt/p238264815"]},{"type":"cover_front_review","sha256":"986ee7c998d2586774e09cda02e0d820d2c79a6ef8add9b582be72101e49ecfb","cover_id":14655590,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://stephenking.com/works/novel/from-a-buick-8.html","reviewed_at":"2026-11-02T17:01:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_author_id":928300049},"before_row":null},{"key":{"edition_id":987202018},"seq":13,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987102014,"evidence":[{"note":"Exact Dutch ISBN9789024539147 binds to From a Buick8. KB copyright2001 does not replace confirmed original release24September2002; retain current2002.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p238264815"],"reference":"work:3325","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["https://stephenking.com/works/novel/from-a-buick-8.html","https://openlibrary.org/works/OL81586W","https://data.bibliotheken.nl/id/nbt/p238264815"]},{"type":"cover_front_review","sha256":"986ee7c998d2586774e09cda02e0d820d2c79a6ef8add9b582be72101e49ecfb","cover_id":14655590,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/14655590-L.jpg?default=false","edition_id":987202018,"bound_title":"Het geheim van de Buick","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789024539147","evidence_url":"https://data.bibliotheken.nl/id/nbt/p238264815","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14655590-M.jpg?default=false","bound_author_id":928300049},"before_row":null},{"key":{"work_id":987102002,"language":"nl"},"seq":14,"relation":"catalog_work_descriptions","after_row":{"text":"William Stoner groeit op in een arm boerengezin in Missouri. Aan de universiteit, waar hij landbouwkunde zou gaan studeren, ontdekt hij de Engelse literatuur. Hij kiest voor een bestaan als docent, ver van het leven dat voor hem leek vast te liggen. Die keuze brengt hem niet vanzelf dichter bij anderen. Zijn huwelijk, familiebanden en loopbaan kennen teleurstellingen en conflicten. John Williams volgt hoe Stoner binnen een ogenschijnlijk bescheiden leven probeert vast te houden aan wat voor hem waarde heeft.","work_id":987102002,"evidence":[{"note":"Exact ISBN9789048813834 and KB title Stoner/John Edward Williams bind to existing John Williams novel1965. Full middle name is not another author. No Work duplication or publisher-origin inference.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p343676869","http://data.bibliotheken.nl/id/nbt/p439037751"],"reference":"work:1346","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","r