dition_id":987202002,"bound_title":"Stoner","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789048813834","evidence_url":"https://data.bibliotheken.nl/id/nbt/p343676869","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/8132062-M.jpg?default=false","bound_author_id":987302004},"before_row":null},{"key":{"work_id":987102016,"language":"nl"},"seq":16,"relation":"catalog_work_descriptions","after_row":{"text":"Al dertig jaar onderzoekt de geheime dienst Southern Reach een gebied dat op onverklaarbare wijze van de buitenwereld is afgesneden. Na de twaalfde expeditie naar Area X is de organisatie ontregeld. John Rodriguez krijgt de leiding en probeert te begrijpen wat er is gebeurd. Hij moet zich daarbij baseren op verhoren, verborgen aantekeningen en verontrustende video-opnamen. Zijn onderzoek richt zich niet alleen op het onbekende gebied, maar ook op de instelling die daar al zo lang vat op probeert te krijgen.","work_id":987102016,"evidence":[{"note":"Exact Dutch ISBN9789023491453 identifies Authority2014/Southern Reach second novel. Jeff VanderMeer typography variants are same established author. Series links unchanged.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p383962404"],"reference":"work:3433","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL17453058W","https://data.bibliotheken.nl/id/nbt/p383962404"]},{"type":"cover_front_review","sha256":"94be631023a2a7e48d899151dec069ebc4ccfeff39fb5c1d0ec407a5f25277b6","cover_id":13948237,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/