rence":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/14553519-L.jpg?default=false","edition_id":987202006,"bound_title":"Het lichaam","reviewed_at":"2026-11-02T17:01:00+00:00","bound_isbn13":"9789045043012","evidence_url":"https://metadata.isbn.nl/1201565/het-lichaam.html","review_batch":"nl-scale-20261102-003","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14553519-M.jpg?default=false","bound_author_id":987302002},"before_row":null},{"key":{"work_id":987102018,"language":"nl"},"seq":37,"relation":"catalog_work_descriptions","after_row":{"text":"Loki is ontsnapt en maakt het dodenschip Naglfar gereed voor een aanval op de goden van Asgard. Magnus Chase en zijn vrienden moeten hem tegenhouden voordat de laatste strijd kan beginnen. Hun tocht voert over de zeeën van verschillende werelden, langs vijandige reuzen en andere gevaren. Magnus heeft hulp gekregen om zich op die opdracht voor te bereiden, maar twijfelt nog aan zijn eigen geschiktheid. Niet alleen de reis, ook het doorgronden van Loki vraagt meer dan strijdvaardigheid.","work_id":987102018,"evidence":[{"note":"Exact Dutch ISBN9789000345496 and KB series identify Magnus Chase book3, same existing Work2017. KB original copyright2016 conflicts with publication chronology and is not used to change current year; original author''s book3 identity and publisher guide substantively checked.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p410917257"],"reference":"work:6346","checked_at":"2026-11-02T17:01:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://rickriordan.com/book/the-ship-of-the-dead/","https://books.disney.com/content/uploads/2017/08/Trials-of-Apollo-Series-2018-v%E2%95%9E%C3%86.pdf","